-- Actual existing persisted review/activation commands; all identities/approvals/funds are rolled-back synthetic fixtures.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('d2100010-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('admin',true,'payment_verified',true))::text,true)$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-m6-confirmation-'||n||'@example.test',now()from generate_series(1,2)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,2)n;
insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)select pg_temp.id(n),'synthetic_fixture','disposable-m6-010:'||n,clock_timestamp()+interval'2 hours'from generate_series(1,2)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic paying owner');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Synthetic payment practice');
update public.doctor_edition_policy set mode='administrative_candidate',revision=revision+1,change_reason='Explicit synthetic M6-010 verification';
insert into public.doctor_saas_terms_versions(id,plan_key,version,status,currency,currency_exponent,monthly_minor,yearly_minor,trial_days,staff_limit,staff_unlimited,clinic_limit,clinic_unlimited,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,terms_document_ref,commercial_approval_ref,legal_approval_ref)values
(pg_temp.id(51),'synthetic-m6-010',1,'approved','EGP',2,29900,243984,0,4,false,1,false,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-m6-010/v1','SYNTHETIC_NOT_COMMERCIAL_APPROVAL','SYNTHETIC_NOT_LEGAL_APPROVAL');
insert into public.doctor_saas_terms_documents(terms_version_id,document_ref,content_en,content_ar)values(pg_temp.id(51),'synthetic-m6-010/v1','Synthetic fixture only; no actual payment or merchant approval.','اختبار اصطناعي فقط دون دفع فعلي أو اعتماد تاجر.');
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(51),revision=2,change_reason='Disposable terms only';
insert into public.doctor_manual_payment_recipients(id,account_key,address_kind,address,beneficiary_name,instructions_en,instructions_ar,currency,currency_exponent,merchant_approval_ref)values(pg_temp.id(71),pg_temp.id(72),'ipa','synthetic-fixture-only@instapay','Synthetic fixture beneficiary','Do not transfer actual funds.','لا تحول أموالاً حقيقية.','EGP',2,'SYNTHETIC_FIXTURE_NOT_MERCHANT_APPROVAL');
update public.doctor_manual_payment_configuration set recipient_id=pg_temp.id(71),enabled=true,acceptance_mode='synthetic',activation_policy='inactive_account_on_review',activation_approval_ref='SYNTHETIC_NOT_LIVE_APPROVAL',revision=2,change_reason='Rolled-back synthetic M6-010 configuration';
create temporary table results(name text primary key,value jsonb);grant all on results to authenticated;
create temporary table moment(value timestamptz);insert into moment values(clock_timestamp()-interval'1 minute');grant select on moment to authenticated;
create function pg_temp.notice(n integer)returns jsonb language plpgsql security invoker as $$declare q jsonb;i jsonb;begin
 q:=public.doctor_create_saas_quote(pg_temp.id(51),2,0,'monthly','synthetic-m6-010/v1',pg_temp.id(200+n));
 i:=public.doctor_prepare_saas_payment((q->>'quote_id')::uuid,pg_temp.id(300+n));
 perform public.doctor_prepare_manual_payment((i->>'intent_id')::uuid,2,pg_temp.id(400+n));
 return public.doctor_submit_manual_payment((i->>'intent_id')::uuid,'SYNTHETIC-M6-CLAIM-'||n,(select value from moment),2,pg_temp.id(500+n));end $$;
create function pg_temp.confirm(p_notice_name text,command integer,minor text default'29900',unit text default'EGP',independent boolean default true,bank text default'SYNTHETIC-BANK-ENTRY')returns jsonb language sql security invoker as $$select public.doctor_review_manual_payment((select(value->>'id')::uuid from results where results.name=p_notice_name),0,'funds_verified','Synthetic independent bank check',bank,minor,unit,(select value from moment),'SYNTHETIC_BANK_RECORD_NOT_REAL_EVIDENCE',independent,pg_temp.id(command))$$;
-- Actual cross-ledger commands inside this rollback; fixture approval markers grant no live authority.
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(31),pg_temp.id(21),'Synthetic acceptance clinic','Etc/UTC');
insert into public.patient_identities(id)values(pg_temp.id(41));
insert into public.practice_patients(id,practice_id,patient_identity_id,display_name,created_location_id,created_by)values(pg_temp.id(42),pg_temp.id(21),pg_temp.id(41),'Synthetic acceptance patient',pg_temp.id(31),pg_temp.id(1));
insert into public.appointments(id,practice_id,doctor_user_id,location_id,patient_id,starts_at,ends_at,timezone,location_name,created_by)values(pg_temp.id(61),pg_temp.id(21),pg_temp.id(1),pg_temp.id(31),pg_temp.id(42),now()+interval'1 day',now()+interval'1 day 20 minutes','Etc/UTC','Synthetic acceptance clinic',pg_temp.id(1));
insert into public.doctor_manual_payment_reviewers(user_id,enabled,revision,approval_ref,valid_until)values(pg_temp.id(2),true,1,'SYNTHETIC_INDEPENDENT_REVIEWER_NOT_REAL_APPROVAL',clock_timestamp()+interval'1 hour');
set local role authenticated;select pg_temp.claim(1);
insert into results values('notice',pg_temp.notice(1));
select is(public.doctor_saas_status()->>'state','unconfigured','checkout claim alone grants no subscription');
select is((select value->>'amount_minor'from results where name='notice'),'29900','synthetic checkout binds frozen plan amount');
select is((select value->>'currency'from results where name='notice'),'EGP','quote currency cannot come from editable browser metadata');
select throws_ok($$select public.doctor_activate_manual_payment((select(value->>'id')::uuid from results where name='notice'),1,pg_temp.id(701))$$,'42501','DOCTOR_INDEPENDENT_REVIEW_REQUIRED','customer cannot promote own checkout claim');
select pg_temp.claim(2);
select throws_ok($$select public.doctor_activate_manual_payment((select(value->>'id')::uuid from results where name='notice'),1,pg_temp.id(702))$$,'40001','DOCTOR_MANUAL_REVIEW_CONFLICT','out-of-order activation cannot invent independent funds');
insert into results values('verified',pg_temp.confirm('notice',703));
select is((select value->>'status'from results where name='verified'),'funds_verified','separate persisted funds evidence exists before activation');
select pg_temp.claim(1);
select is(public.doctor_saas_status()->>'state','unconfigured','funds verification remains separate from entitlement');
select pg_temp.claim(2);
insert into results values('activated',public.doctor_activate_manual_payment((select(value->>'id')::uuid from results where name='notice'),1,pg_temp.id(704)));
select is(public.doctor_activate_manual_payment((select(value->>'id')::uuid from results where name='notice'),1,pg_temp.id(704)),(select value from results where name='activated'),'duplicate activation retains exact original period');
select is(pg_temp.confirm('notice',703)->>'status','funds_verified','old acknowledgement cannot rewrite current activation');
select pg_temp.claim(1);
insert into results values('subscription',public.doctor_saas_status());
select is((select value->>'state'from results where name='subscription'),'paid','only configured synthetic reviewed activation admits paid period');
select is((select value->>'live_activation'from results where name='subscription'),'false','synthetic paid state is never actual live commercial approval');
select is(public.doctor_manual_payment_configuration()->>'live_acceptance_enabled','false','no live merchant route is activated');
insert into results values('renewal',public.doctor_request_saas_lifecycle('renewal',(select(value->>'revision')::integer from results where name='subscription'),(select(value#>>'{period,id}')::uuid from results where name='subscription'),pg_temp.id(51),'synthetic-m6-010/v1',true,pg_temp.id(705)));
select is((select value->>'status'from results where name='renewal'),'requested','renewal intake records request rather than executing unapproved policy');
select is((select value->>'entitlement_changed'from results where name='renewal'),'false','renewal acknowledgement does not extend period');
select is((select value->>'provider_confirmation'from results where name='renewal'),null::text,'no provider confirmation is invented');
select is(public.doctor_saas_status()->'period',(select value->'period'from results where name='subscription'),'renewal request preserves exact subscription period');
insert into results values('price',public.doctor_write_service_price(pg_temp.id(21),pg_temp.id(31),null,0,'Synthetic accepted service','12555','EGP',2,pg_temp.id(706)));
insert into results values('charge',public.doctor_write_visit_charge(pg_temp.id(21),pg_temp.id(31),pg_temp.id(61),1,pg_temp.id(42),(select(value->>'id')::uuid from results where name='price'),2,null,0,'Synthetic acceptance charge',pg_temp.id(707)));
select is((select value->>'amount_minor'from results where name='charge'),'25110','exact integer multiplication creates no rounding artifact');
reset role;
create function pg_temp.payment(kind text,minor text,key integer,original uuid default null)returns jsonb language sql security invoker as $$select public.doctor_prepare_practice_payment(pg_temp.id(21),pg_temp.id(31),kind,(select(value->>'id')::uuid from results where name='charge'),original,minor,'Synthetic cross-ledger acceptance',pg_temp.id(key))$$;
create function pg_temp.advance(p_name text,revision integer,action text,key integer,outcome text default null)returns jsonb language sql security invoker as $$select public.doctor_advance_practice_payment(pg_temp.id(21),pg_temp.id(31),(select(value->>'id')::uuid from results where results.name=p_name),revision,action,outcome,pg_temp.id(key))$$;
create function pg_temp.total(field text)returns text language sql security invoker as $$select g->>field from jsonb_array_elements(public.doctor_practice_financial_report(pg_temp.id(21))->'totals')g where g->>'currency'='EGP'and g->>'currency_exponent'='2'$$;
set local role authenticated;select pg_temp.claim(1);
insert into results values('collection',pg_temp.payment('collection','10000',708));
select throws_ok($$select pg_temp.advance('collection',1,'reconcile',709)$$,'40001','DOCTOR_PRACTICE_ACCEPTANCE_EVIDENCE_REQUIRED','out-of-order reconciliation cannot invent movement acceptance');
insert into results values('unknown',pg_temp.advance('collection',1,'dispatch',710,'accepted'));
select is(pg_temp.total('collections_minor'),'0','persisted synthetic acceptance alone creates no posted total');
select is(pg_temp.total('reserved_collection_minor'),'10000','interrupted reconciliation retains exact reservation');
select is(pg_temp.total('unknown_count'),'1','interrupted movement remains visibly unknown');
select is(pg_temp.advance('collection',1,'dispatch',710,'accepted'),(select value from results where name='unknown'),'duplicate original dispatch recovers acknowledgement without another send');
select throws_ok($$select pg_temp.advance('collection',2,'dispatch',711,'accepted')$$,'40001','DOCTOR_PRACTICE_RECONCILIATION_REQUIRED','unknown outcome cannot blindly resend with a fresh key');
insert into results values('posted',pg_temp.advance('collection',2,'reconcile',712));
select is(pg_temp.advance('collection',2,'reconcile',712),(select value from results where name='posted'),'duplicate reconciliation creates no extra receipt');
select is(pg_temp.total('collections_minor'),'10000','report reconciles exact immutable collection entry');
select is(pg_temp.total('reserved_collection_minor'),'0','posted result clears only its prior reservation');
insert into results values('refund',pg_temp.payment('refund','3000',713,(select(value#>>'{entry,id}')::uuid from results where name='posted')));
select lives_ok($$select pg_temp.advance('refund',1,'dispatch',714,'accepted')$$,'refund outcome is separately persisted before acknowledgement');
insert into results values('reversal',pg_temp.advance('refund',2,'reconcile',715));
select is((select value#>>'{entry,original_entry_id}'from results where name='reversal'),(select value#>>'{entry,id}'from results where name='posted'),'reversal references original collection rather than SaaS bank evidence');
select is(pg_temp.total('charges_minor'),'25110','refund never erases original issued charge');
select is(pg_temp.total('refunds_minor'),'3000','refund report matches original-linked reversal');
select is(pg_temp.total('outstanding_minor'),'18110','charge less net posted money is exact');
select is(pg_temp.total('discrepancy_count'),'0','completed synthetic cross-ledger journey has no unresolved discrepancy');
select is(pg_temp.total('unknown_count'),'0','interrupted outcomes are reconciled, not hidden');
select is(public.doctor_saas_status()->'period',(select value->'period'from results where name='subscription'),'practice collection/refund never changes SaaS period or entitlement');
select is(public.doctor_practice_financial_source(pg_temp.id(21),'ledger',(select(value#>>'{entry,id}')::uuid from results where name='reversal'))->'details'->>'original_receipt_label','SYN-00000001','report source retains original scoped synthetic receipt');
select is(public.doctor_practice_financial_report(pg_temp.id(21))->>'tax_applicability','unreviewed','cross-ledger success cannot supply qualified tax applicability');
select is(public.doctor_practice_financial_report(pg_temp.id(21))->>'provider_payout','unavailable','provider payout is not patient revenue');
select pg_temp.claim(2);
select throws_ok($$select public.doctor_practice_financial_report(pg_temp.id(21))$$,'42501','DOCTOR_BILLING_OWNER_REQUIRED','SaaS reviewer authority grants no patient-money report access');
reset role;
select is((select count(*)::integer from public.doctor_saas_periods where kind='manual_paid'),1,'patient receipts and renewal request create no extra SaaS period');
select is((select count(*)::integer from public.doctor_manual_received_funds),1,'SaaS funds evidence is independent of practice receipts');
select is((select count(*)::integer from public.doctor_practice_ledger_entries),2,'one collection and one original-linked reversal only');
select is((select count(*)::integer from doctor_private.synthetic_practice_payment_acceptances),2,'retries and report reads never duplicate synthetic transport acceptance');
select ok(not exists(select 1 from doctor_private.command_receipts where command_key in(pg_temp.id(701),pg_temp.id(702),pg_temp.id(709),pg_temp.id(711))),'denied/out-of-order operations leave no successful receipt');
select * from finish();rollback;
